/// <summary>
/// PricingAttribute of table <c>CustTable</c> field PriceGroup.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Customer, GUPPricingAttributeSourceLevel::Header)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(CustTable, PriceGroup))]
internal class GUPPricingAttributeCustTablePriceGroup extends GUPPricingAttributeCustTable implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustTable, PriceGroup);
}

public Set getAllowedValuesWithDescription()
{
    var ret = new Set(Types::AnyType);

    Custtable       custTable;
    PriceDiscGroup  priceDiscGroup;

    while select PriceGroup from custtable
        group by PriceGroup
        join priceDiscGroup
        group by GroupId, Name, Type
        where custTable.PriceGroup == priceDiscGroup.GroupId && PriceDiscGroup.Type == PriceGroupType::PriceGroup
    {
        GUPPricingAttributeAllowedValuesObject valueObject =
            new GUPPricingAttributeAllowedValuesObject(priceDiscGroup.GroupId, priceDiscGroup.Name);
        ret.add(valueObject);
    }
    return ret;
}
